    "estimateFieldSourceAndConfidence": false
  },
  "fieldSchema": {
    "fields": {
      "NumeroDDT": {
        "type": "string",
        "method": "extract",
        "description": "Numero del documento di trasporto, in alto; etichette: \"DDT n.\", \"Bolla n.\".",
        "estimateSourceAndConfidence": true
