        "type": "date",
        "method": "extract",
        "description": "Data di consegna nella sezione \"Dati di trasporto\".",
        "estimateSourceAndConfidence": true
      },
      "Colli": {
        "type": "number",
        "method": "extract",
        "description": "Numero di colli, in fondo; etichette: \"N. colli\", \"Colli\".",
        "estimateSourceAndConfidence": true
      },
      "Vettore": {
        "type": "string",
        "method": "extract",
        "description": "Nome del trasportatore nella sezione \"Vettore\".",
        "estimateSourceAndConfidence": true
      },
      "Causale": {
        "type": "string",
        "method": "classify",
        "enum": [
          "vendita",
          "reso",
          "conto visione",
          "altro"
        ],
        "description": "Categoria del documento in base al contenuto."
      },
